[""import kotlinx.coroutines.sync.Semaphore
import kotlinx.coroutines.sync.withPermit
import org.springframework.stereotype.Service
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RestController

@Service
class MyService {
    private val semaphore = Semaphore(50) // Limit to max 50 concurrent requests

    suspend fun handleRequest(): String {
        semaphore.withPermit {
            // Acquire a connection and process the request
            Thread.sleep(100) // Simulate work
            return ""Request processed""
        }
    }
}

@RestController
@RequestMapping(""/api"")
class MyController(private val service: MyService) {

    @GetMapping(""/process"")
    suspend fun process(): String {
        return service.handleRequest()
    }
}

